mapper.select:
SELECT tag_id, tag_name, tag_type, tag_use_count, created_at
FROM tag
WHERE tag_id = #{tagId}

SELECT tag_id, tag_name, tag_type, tag_use_count, created_at
FROM tag
WHERE tag_name = #{tagName} AND tag_type = #{tagType}

mapper.update:
UPDATE tag
SET tag_use_count = tag_use_count + 1
WHERE tag_id = #{tagId}

UPDATE tag
SET tag_use_count = GREATEST(tag_use_count - 1, 0)
WHERE tag_id = #{tagId}

mapper.delete:
DELETE FROM tag
WHERE tag_id = #{tagId}
AND tag_use_count = 0

mapper.select:
SELECT COUNT(*) > 0
FROM image_tag
WHERE tag_id = #{tagId}

SELECT COUNT(*) > 0
FROM image_tag
WHERE image_id = #{imageId} AND tag_id = #{tagId}
